const json = (data,status=200)=>new Response(JSON.stringify(data),{status,headers:{"Content-Type":"application/json; charset=utf-8","Cache-Control":"no-store"}});
export async function onRequestGet({request,env}) {
  if (!env.DB) return json({error:"Order status is not available."},503);
  const id = new URL(request.url).searchParams.get("order") || "";
  // IDs generated by crypto.randomUUID() are UUIDs; reject other values.
  if (!/^[0-9a-f-]{36}$/i.test(id)) return json({error:"Order reference is invalid."},400);
  try {
    const order = await env.DB.prepare("SELECT payment_status FROM orders WHERE id=?").bind(id).first();
    if (!order) return json({error:"Order not found."},404);
    return json({status:order.payment_status});
  } catch {
    return json({error:"Order status is temporarily unavailable."},500);
  }
}
